// Liste des entreprises à analyser (nom, stand, salon, fonds pressenti à l'étape 1).
// Exemple : remplacez ces lignes par votre propre liste d'exposants.
const ROWS = [
 { "Entreprise": "Exemple Hydro SAS", "Stand": "7.2 A01", "Salon": "Maires", "Fonds": "CCR-F", "Priorité précédente": "Étape 2" },
 { "Entreprise": "Exemple Renov Énergie", "Stand": "7.2 B02", "Salon": "Maires", "Fonds": "Protect", "Priorité précédente": "Étape 2" },
 { "Entreprise": "Exemple Génie Écologique", "Stand": "7.1 C03", "Salon": "Biodiversité", "Fonds": "Objectif Biodiversité", "Priorité précédente": "Étape 1 (faux négatif)" }
];
return ROWS.map(r => ({ json: r }));

// One item per company that passed step 2. The fund decided at step 2 chooses the prompt.
const cfg = $('Config').first().json;
const only = (cfg.only || []).map(String);
const rows = $input.all().map(i => i.json).filter(r => !only.length || only.includes(r.Entreprise));
const start = Number(cfg.offset) || 0;
const end = cfg.limit ? start + Number(cfg.limit) : undefined;
return rows.slice(start, end).map(r => ({ json: { c: { name: r.Entreprise, stand: r.Stand, salon: r.Salon, fonds: r.Fonds, prev: r['Priorité précédente'] || '' } } }));

// ---- Shared helpers (prepended to several Code nodes) ----
function geminiJson(res) {
  if (!res || res.error) {
    const e = res && res.error;
    throw new Error('API call: ' + (typeof e === 'string' ? e : ((e && e.message) || JSON.stringify(e))));
  }
  const cand = res.candidates && res.candidates[0];
  if (!cand) throw new Error('Empty response' + (res.promptFeedback ? ': ' + JSON.stringify(res.promptFeedback) : ''));
  const parts = (cand.content && cand.content.parts) || [];
  const txt = parts.filter(p => !p.thought).map(p => p.text || '').join('');
  if (!txt) throw new Error('No text (finishReason: ' + (cand.finishReason || '?') + ')');
  const i = txt.indexOf('{'), j = txt.lastIndexOf('}');
  if (i < 0 || j < i) throw new Error('No JSON in answer: ' + txt.slice(0, 120));
  return JSON.parse(txt.slice(i, j + 1));
}
function domainOf(s) {
  return String(s || '').toLowerCase().trim().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split(/[\/?#\s]/)[0];
}
// The pages Gemini actually consulted (Google Search results it used, pages it opened).
function consultedSources(res) {
  const cand = (res && res.candidates && res.candidates[0]) || {};
  const out = [];
  const gm = cand.groundingMetadata || {};
  for (const ch of gm.groundingChunks || []) { const w = ch.web || {}; out.push({ title: w.title || w.domain || 'source', uri: w.uri || '', domain: domainOf(w.domain || w.title) }); }
  const um = (cand.urlContextMetadata || cand.url_context_metadata || {}).urlMetadata || [];
  for (const u of um) if (/SUCCESS/.test(u.urlRetrievalStatus || '')) out.push({ title: domainOf(u.retrievedUrl), uri: u.retrievedUrl, domain: domainOf(u.retrievedUrl) });
  const seen = new Set();
  return out.filter(x => x.domain && !seen.has(x.domain) && seen.add(x.domain));
}
function geminiRequest(system, userText, thinking, search) {
  const r = { systemInstruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts: [{ text: userText }] }] };
  if (search) r.tools = [{ google_search: {} }, { url_context: {} }];
  if (thinking) r.generationConfig = { thinkingConfig: { thinkingLevel: thinking } };
  return r;
}
const CATS = ['P1', 'P2', 'À SUIVRE', 'PASS'];
