  const expected = !a ? category : passWithReason && !passStep3 ? 'PASS' : rule(imp, impD, others, a.pertinence);
  const meet = !!LABEL[category];
  const tab = category === 'P1' || category === 'P2' ? 'rencontrer' : category === 'À SUIVRE' ? 'suivre' : '';
  const firstUrl = a ? [a.impact && a.impact.source, a.traction && a.traction.source, a.profil_source].find(isUrl) : '';
  // Two-step method: 1 = list of the salon; 2a = profile, stage and thesis checked by the AI; 2b = proofs.
  const sortie = category === 'PASS' ? (passStep3 ? 'Étape 2b' : 'Étape 2a') : SORTIE[category];
  const resultat = category === 'PASS' ? `${sortie} – Pass${x.routed_out ? '' : ' ' + c.fonds} : ${a.motif_pass || (passStep3 ? 'aucune preuve vérifiée' : 'hors profil')} (workflow)`
    : meet ? `Retenu – ${LABEL[category]} (${nOk} preuve(s) ✓, pertinence ${a.pertinence}/3) (workflow)`
    : `Erreur technique : ${x.error} (relancer)`;
  const srcUrl = category === 'PASS' ? (isUrl(a.motif_source) ? a.motif_source : a.profil_source) : firstUrl;
  return {
    order: ORDER[category] ?? 9, pert: a ? a.pertinence : 0, nOk,
    tab, rencontrer: meet ? {
      'Priorité': LABEL[category], 'Entreprise': c.name, 'Fonds': c.fonds + (c.routing && c.routing.fonds_secondaire && c.routing.fonds_secondaire !== 'Aucun' ? ' (+ ' + c.routing.fonds_secondaire + ')' : ''), 'Pourquoi les rencontrer': a.pourquoi, 'Stand': c.stand,
      'Profil (type, CA, source)': cell([a.profil_type, a.chiffre_affaires ? 'CA ' + a.chiffre_affaires : 'CA non publié', a.profil].filter(Boolean).join(' · ') + (isUrl(a.profil_source) ? ` (${host(a.profil_source)})` : ''), a.profil_source),
      'Type de deal': a.type_deal || 'À déterminer', 'Impact': proofCell(a.impact), 'Traction': proofCell(a.traction), 'Potentiel': proofCell(a.potentiel), 'Question à poser': a.question,
    } : null,
    exposant: { 'Entreprise': c.name, 'Stand': c.stand, 'Salon': c.salon, 'Fonds visé': c.fonds, 'Sortie': sortie, 'Résultat': resultat,
      'Source': isUrl(srcUrl) ? cell(site({ source: srcUrl, site: '' }), srcUrl) : '' },
    audit: { 'Entreprise': c.name, 'Fonds IA': c.routing ? c.routing.fonds : '', 'Fonds étape 1': c.fonds_etape1 || '', 'Fonds changé': c.routing && c.fonds_etape1 && c.routing.fonds !== c.fonds_etape1 ? 'oui' : '', 'Fonds secondaire': c.routing ? c.routing.fonds_secondaire : '', 'Justification fonds': c.routing ? c.routing.justification : '', 'Décision IA': category, 'Pertinence': a ? a.pertinence : '', 'Preuves ✓ avec URL': a ? nOk : '',
      'Impact ✓': a ? (imp ? 'oui' : 'non') : '', 'Type de deal': a ? a.type_deal : '', 'Contrôle règle': !a ? '' : expected === category ? 'OK' : `Écart : la règle donne ${expected}`, 'Priorité précédente': c.prev,
      'Identité': a ? a.identite : '', 'Verticale': a ? a.verticale : '', 'Verdict profil': a ? a.verdict_profil : '', 'Pertinence (raison)': a ? a.pertinence_raison : '',
      'Raisonnement': a ? a.raisonnement : '', 'Recherche Google faite': c.searched ? 'oui' : 'NON', 'Recherches Google': (c.queries || []).join(' | '), 'Pages consultées': (c.sources || []).map(s => s.domain).join(' '),
      '2e essai': x.retried ? 'oui' : '', 'Erreur': x.error || '' },
  };
});
// P1, then P2, then À suivre; alphabetical inside each priority.
out.sort((p, q2) => p.order - q2.order || p.audit.Entreprise.localeCompare(q2.audit.Entreprise, 'fr', { sensitivity: 'base' }));
return out.map(o => ({ json: o }));
